You are evaluating a source-code privacy technique. Your job is to defeat it.

A tool called `effigy` takes a source file from some **original problem domain** and rewrites or
obscures it so the file can be sent to a third-party model for architectural review without
revealing what the original code was about. You are that third party, and you are hostile.

You have **complete knowledge of the tool**. It is a public research repository: its algorithms,
its configuration, and its prompts are all published. Assume nothing is secret except the original
source itself. Specifically:

Solution `literal-tagging` — string-literal and PII tagging with type-class placeholders.

Every string literal is replaced by a typed placeholder such as `<URL:n>`, `<PATH:n>`, `<MSG:n>`.
The same literal content maps to the same placeholder throughout the file, so deduplication and
coupling are preserved. Triple-quoted, double-quoted, single-quoted and backtick literals are all
matched.

**Identifiers, comments and code structure are untouched.** Every function, variable, type, field,
table and column name survives exactly as written in the original.

**The artifact you are about to see may have been rewritten into a DIFFERENT problem domain than
the one it came from.** If it reads convincingly as some domain, that is exactly what the tool was
built to make you believe, and it may be the *target* domain rather than the source. Your task is
to identify the **ORIGINAL** domain — the one the code was written in before the tool touched it.


## The artifact

One source file.

```tsx
import { useState, type FormEvent } from "<MSG:0>";
import type { ExceptionPatch, Read } from "<PATH:0>";

interface FormState {
  toleranceFlag: boolean;
  reason: string;
  requeue: boolean;
}

interface ExceptionFormProps {
  read: Read;
  saving: boolean;
  onCancel: () => void;
  onSave: (patch: ExceptionPatch) => void;
}

const REASON_CODES = ["<MSG:1>", "<MSG:2>", "<MSG:3>", "<MSG:4>"];

function initialState(r: Read): FormState {
  return {
    toleranceFlag: r.toleranceFlag,
    reason: r.exceptionReason ?? "<EMPTY:0>",
    requeue: false,
  };
}

// This restates the server-side validator in TypeScript. The authority is
// api/internal/api/reads.go, (*exceptionPatch).validate — the rule below,
// and the exact message text it returns, are a hand-maintained second copy
// of what that method already enforces. Nothing keeps the two in step.
function validate(s: FormState): string | null {
  if (s.reason !== "<EMPTY:0>" && !REASON_CODES.includes(s.reason)) {
    return `<SQL:0>`;
  }
  if (!s.toleranceFlag && s.requeue) {
    return "<MSG:5>";
  }
  return null;
}

// toleranceFlag and requeue are compared by value; reason is compared to the
// read's stored value trimmed. The three checks decide which fields end up
// in the patch body — an unflagged read that is simply re-saved sends none.
function buildPatch(r: Read, s: FormState): ExceptionPatch {
  const patch: ExceptionPatch = {};
  if (s.toleranceFlag !== r.toleranceFlag) {
    patch.toleranceFlag = s.toleranceFlag;
  }
  const reason = s.reason.trim();
  if (reason !== (r.exceptionReason ?? "<EMPTY:0>")) {
    patch.reason = reason;
  }
  if (s.requeue) {
    patch.requeue = true;
  }
  return patch;
}

export function ExceptionForm({ read, saving, onCancel, onSave }: ExceptionFormProps) {
  const [state, setState] = useState<FormState>(() => initialState(read));
  const [error, setError] = useState<string | null>(null);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const problem = validate(state);
    if (problem !== null) {
      setError(problem);
      return;
    }
    setError(null);
    onSave(buildPatch(read, state));
  };

  return (
    <form className="<MSG:6>" onSubmit={submit}>
      <h2>Flag {read.readId}</h2>
      {error && <p className="<MSG:7>">{error}</p>}
      <p className="<MSG:8>">
        Recorded value {read.readValue} on {read.readDate}, meter {read.meterId}. Flagging
        never changes this value — it only marks the read and, optionally, requeues it.
      </p>

      <label htmlFor="<MSG:9>">
        <input
          id="<MSG:9>"
          type="<MSG:10>"
          checked={state.toleranceFlag}
          onChange={(e) => setState({ ...state, toleranceFlag: e.target.checked })}
        />
        Outside tolerance
      </label>

      <label htmlFor="<MSG:11>">Reason</label>
      <select
        id="<MSG:11>"
        value={state.reason}
        onChange={(e) => setState({ ...state, reason: e.target.value })}
      >
        <option value="<EMPTY:0>">No reason recorded</option>
        {REASON_CODES.map((code) => (
          <option key={code} value={code}>
            {code}
          </option>
        ))}
      </select>

      <label htmlFor="<MSG:12>">
        <input
          id="<MSG:12>"
          type="<MSG:10>"
          checked={state.requeue}
          disabled={!state.toleranceFlag}
          onChange={(e) => setState({ ...state, requeue: e.target.checked })}
        />
        Requeue for a field re-read
      </label>

      <p className="<MSG:8>">
        Requeuing opens a new pending RE-READ record against this meter and leaves this
        read as the exception on file; it does not overwrite the value above.
      </p>

      <div className="<MSG:13>">
        <button type="<MSG:14>" className="<MSG:15>" disabled={saving}>
          {saving ? "<MSG:16>" : "<MSG:17>"}
        </button>
        <button type="<MSG:18>" className="<MSG:19>" onClick={onCancel} disabled={saving}>
          Cancel
        </button>
      </div>
    </form>
  );
}

